// Builds packages/map/src/engine.generated.ts: the map engine (HTML + style + engine JS + pin art) as one string.
// Pin art is taken from the brand board's illustrations, so pins match the rest of the app.
// Run: node packages/map/scripts/build-engine.mjs   (the generated file is committed; teammates do not need to run this)
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const pkg = join(here, '..');
const board = readFileSync(join(pkg, '../../docs/brand/brand-board.html'), 'utf8');

// 1. illustrations from the Modules section of the board: label -> inner svg markup
const start = board.indexOf('<div class="mods">');
const end = board.indexOf('</section>', start);
const block = board.slice(start, end);
const labelToId = { Events: 'events', Buddy: 'buddy', Forum: 'forum', Transit: 'transit', Parkie: 'parkie', 'Visitor info': 'visitorInfo', Assistant: 'assistant', Utilities: 'utilities', Wallet: 'wallet', Feedback: 'feedback', Safety: 'safety', Smell: 'smell', Dashboard: 'dashboard' };
const art = {};
for (const m of block.matchAll(/<div class="mod"><svg class="sp"[^>]*>([\s\S]*?)<\/svg>([^<]+)<\/div>/g)) {
  const id = labelToId[m[2].trim()];
  if (id) art[id] = m[1].replace(/\s+/g, ' ').trim();
}
if (Object.keys(art).length !== 13) throw new Error('expected 13 board illustrations, found ' + Object.keys(art).length);

// 2. extra pin art for kinds that have no module illustration (same flat language: filled shapes, palette only)
Object.assign(art, {
  home: '<path d="M10 48V28Q10 24 14 22Q18 20 20 15Q22 10 28 10Q34 10 36 15Q38 20 42 22Q46 24 46 28V48Z" fill="#FF7A2F"/><path d="M23 48V38a5 5 0 0 1 10 0V48Z" fill="#fff"/>',
  work: '<rect x="9" y="19" width="38" height="27" rx="7" fill="#3D5BFF"/><path d="M21 19v-3a4 4 0 0 1 4-4h6a4 4 0 0 1 4 4v3" fill="none" stroke="#3A2F5C" stroke-width="3" stroke-linecap="round"/><rect x="9" y="30" width="38" height="4" fill="#8FA3FF"/><rect x="25" y="28" width="6" height="8" rx="2" fill="#fff"/>',
  note: '<path d="M12 12h32a2 2 0 0 1 2 2v22l-12 12H14a2 2 0 0 1-2-2Z" fill="#FFB88A"/><path d="M34 48V38a2 2 0 0 1 2-2h10Z" fill="#FF7A2F"/><path d="M19 22h18M19 29h12" stroke="#3A2F5C" stroke-width="3" stroke-linecap="round" fill="none"/>',
  lostFound: '<circle cx="17" cy="24" r="4.5" fill="#FF7A2F"/><circle cx="28" cy="16" r="4.5" fill="#FF7A2F"/><circle cx="39" cy="24" r="4.5" fill="#FF7A2F"/><path d="M28 29c-7 0-12 6-12 11 0 5 5 6 8 5 3-1 5-1 8 0 3 1 8 0 8-5 0-5-5-11-12-11Z" fill="#FFB88A"/>',
});

// 3. assemble
const template = readFileSync(join(pkg, 'engine/template.html'), 'utf8');
const style = readFileSync(join(pkg, 'engine/style.js'), 'utf8');
const engine = readFileSync(join(pkg, 'engine/engine.js'), 'utf8');
const html = template
  .replace('/*__PIN_ART__*/{}', () => JSON.stringify(art))
  .replace('/*__STYLE__*/', () => style)
  .replace('/*__ENGINE__*/', () => engine);
if (html.includes('__PIN_ART__*/') || html.includes('/*__STYLE__*/') || html.includes('/*__ENGINE__*/')) throw new Error('template placeholder was not replaced');

const keys = Object.keys(art);
const out = `// GENERATED by packages/map/scripts/build-engine.mjs. Do not edit by hand; edit packages/map/engine/* and re-run the script.
export const ENGINE_HTML = ${JSON.stringify(html)};

export const PIN_ART_KEYS = ${JSON.stringify(keys)} as const;
export type PinArtKey = (typeof PIN_ART_KEYS)[number];

/** the same illustrations as raw SVG markup (56 x 56), for rendering outside the map (kind picker, lists) */
export const PIN_ART: Record<PinArtKey, string> = ${JSON.stringify(art)};
`;
writeFileSync(join(pkg, 'src/engine.generated.ts'), out);
// optional: `node build-engine.mjs path/to/engine.html` also writes the standalone page, for debugging in a browser
if (process.argv[2]) writeFileSync(process.argv[2], html);
// the website uses the same map and the same illustrations: write them where apps/web serves them from
const webDir = join(pkg, '../../apps/web');
writeFileSync(join(webDir, 'map-engine.html'), html);
writeFileSync(join(webDir, 'src/art.js'), `// GENERATED by packages/map/scripts/build-engine.mjs: the flat illustrations (56 x 56 SVG markup), same as the app.
export const ART = ${JSON.stringify(art, null, 1)};
`);
console.log(`engine built: ${html.length} chars, ${keys.length} pin illustrations (${keys.join(', ')})`);
